<?php
function rwTimelineHeaders():array{return ['Sequence','Activity','Start Date','Deadline','Student','Supervisor','DAA','Phase','Evaluator Visible'];}
function rwTemplate(int $year):array{
 rwRequire($year>=2020&&$year<=2100,'Enter a valid starting academic year.');$source=json_decode(file_get_contents(__DIR__.'/timeline-template.json'),true,512,JSON_THROW_ON_ERROR);
 $dates=[['07-01','07-31'],['08-01','08-31'],['09-22','09-22'],['10-07','10-07'],['10-14','10-14'],['10-18','10-18'],['10-19','10-19'],['10-20','10-24'],['10-27','10-27'],['11-06','11-06'],['04-01','04-01'],['04-10','04-10'],['04-20','04-20'],['04-30','04-30'],['05-11','05-11'],['05-11','05-11'],['05-25','05-25'],['06-02','06-03'],['06-15','06-15'],['06-19','06-19'],['06-22','06-22'],['06-23','06-23'],['06-24','06-24'],['06-30','06-30']];$rows=[];
 foreach($source as $i=>$r){$y=$year+($i>=10?1:0);$rows[]=[$i+1,$r[0],$y.'-'.$dates[$i][0],$y.'-'.$dates[$i][1],$r[3],$r[4],$r[5]??'–',$i<10?'Proposal development':($i<15?'Research & drafts':($i<18?'Evaluation & defense':'Final submission')),(int)in_array($i,[15,16],true)];}return $rows;
}
function rwReadTimeline(array $p):array{
 if(($p['template']??'')==='1')return rwTemplate((int)($p['year']??0));
 $f=$_FILES['timeline']??[];rwRequire(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']<=1024*1024&&is_uploaded_file($f['tmp_name']),'Upload a timeline CSV up to 1 MB.');$h=fopen($f['tmp_name'],'r');$headers=fgetcsv($h);$headers[0]=ltrim($headers[0]??'',"\xEF\xBB\xBF");rwRequire($headers===rwTimelineHeaders(),'Use the downloaded timeline CSV headers.');$rows=[];$seen=[];while(($row=fgetcsv($h))!==false){if($row===[null])continue;rwRequire(count($row)===9&&count($rows)<100,'Use nine columns and at most 100 milestones.');$row=array_map('trim',$row);rwRequire(ctype_digit($row[0])&&(int)$row[0]>0&&!isset($seen[$row[0]]),'Milestone sequence must be unique and positive.');$seen[$row[0]]=true;rwRequire($row[1]!==''&&mb_strlen($row[1])<=240&&dateValid($row[2])&&dateValid($row[3])&&$row[2]<=$row[3],'Check activity and ISO dates YYYY-MM-DD.');foreach([4,5,6]as $i)rwRequire(mb_strlen($row[$i])<=3000,'Action text is too long.');rwRequire(mb_strlen($row[7])<=80&&in_array($row[8],['0','1'],true),'Check phase and evaluator visibility (0/1).');$row[0]=(int)$row[0];$row[8]=(int)$row[8];$rows[]=$row;}fclose($h);rwRequire((bool)$rows,'Timeline has no activities.');return $rows;
}
function rwExport(array $u):never{rwRequire(researchAccess($u),'Research access required.');$pid=(int)($_GET['period']??0);if($pid){$p=one('SELECT * FROM research_periods WHERE id=?',[$pid]);rwRequire($p&&(researchManager($u)||$p['department']===$u['department']),'Timeline unavailable.');$data=[];foreach(all('SELECT * FROM research_milestones WHERE period_id=? ORDER BY sequence_no',[$pid])as $r)$data[]=[$r['sequence_no'],$r['title'],$r['start_date'],$r['due_date'],$r['student_action'],$r['supervisor_action'],$r['coordinator_action'],$r['phase'],$r['evaluator_visible']];}else $data=rwTemplate((int)($_GET['year']??date('Y')));header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="research-timeline.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,rwTimelineHeaders());foreach($data as $row)fputcsv($f,array_map(fn($x)=>preg_match('/^[=+@\-\t\r]/',(string)$x)?"'".$x:$x,$row));fclose($f);exit;}
